'use strict';

const fs = require('fs');
const path = require('path');

const dir = __dirname;

function readNumber(name) {
  const file = path.join(dir, name);
  if (!fs.existsSync(file)) {
    throw new Error(`missing required file: ${name}`);
  }
  const raw = fs.readFileSync(file, 'utf8').trim();
  if (raw === '') {
    throw new Error(`empty required file: ${name}`);
  }
  const value = Number(raw);
  if (!Number.isFinite(value)) {
    throw new Error(`non-numeric value in ${name}: ${JSON.stringify(raw)}`);
  }
  return value;
}

function assertEqual(label, actual, expected) {
  if (actual !== expected) {
    throw new Error(`${label}: expected ${expected}, got ${actual}`);
  }
  console.log(`ok ${label}: ${actual}`);
}

const seed = readNumber('seed.txt');
const stage1 = readNumber('stage1.txt');
const stage2 = readNumber('stage2.txt');
const stage3 = readNumber('stage3.txt');

assertEqual('stage1 === seed + 2', stage1, seed + 2);
assertEqual('stage2 === stage1 * stage1', stage2, stage1 * stage1);
assertEqual('stage3 === stage2 - 4', stage3, stage2 - 4);

console.log(`verified pipeline: seed=${seed} stage1=${stage1} stage2=${stage2} stage3=${stage3}`);

